    /**
     * Retrieves the description for a given stock or ETF.
     * 
     * @param array<string, mixed> $stock
     */
    public static function getDescription(array $stock): string
    {
        $ticker = $stock['ticker'];
        $base = self::DESCRIPTIONS[$ticker] ?? "{$stock['name']} ($ticker) is a publicly traded company listed on the Lakebird Exchange, operating within the {$stock['sector']} sector.";

        if (isset($stock['type']) && $stock['type'] === 'etf') {
            return $base;
        }

        // Append dynamic stats for regular stocks
        return $base;
    }

    /**
     * Retrieves the CEO quote for a given stock ticker.
     */
    public static function getQuote(string $ticker): ?string
    {
        return self::QUOTES[$ticker] ?? null;
    }
